      function printContract() {
        // 设置页面缩放为85%
        document.body.style.zoom = "85%";
        // 印章做反向缩放补偿，保证实际打印尺寸仍为56×56mm
        document.querySelectorAll('.contract-stamp').forEach(function(el) {
          el.style.zoom = "117.65%";
        });
        // 延迟执行打印，确保缩放和页码计算生效
        setTimeout(function() {
          calculatePages();
          window.print();
          // 打印完成后恢复默认缩放
          document.body.style.zoom = "100%";
          document.querySelectorAll('.contract-stamp').forEach(function(el) {
            el.style.zoom = "100%";
          });
        }, 100);
      }
      
      // 计算总页数
      function calculatePages() {
        const body = document.body;
        const pageHeight = (297 - 10 - 20) * 96 / 25.4; // A4可打印区域高度（减去上下边距）
        const printButton = document.querySelector('.print-button');
        const printButtonHeight = printButton ? printButton.offsetHeight : 0;
        const bodyHeight = body.offsetHeight - printButtonHeight;
        const totalPages = Math.ceil(bodyHeight / pageHeight);
        
        // 更新所有页脚的总页数
        const totalPagesElements = document.querySelectorAll('#totalPages');
        totalPagesElements.forEach(el => {
          el.textContent = totalPages.toString();
        });
        
        // 如果只有一页，隐藏页脚
        if (totalPages <= 1) {
          const footers = document.querySelectorAll('.footer');
          footers.forEach(f => {
            f.style.display = 'none';
          });
        }
      }
      
      // 页面加载完成后执行
      window.onload = function() {
        calculatePages();
        
        // 在打印前更新页码
        window.addEventListener('beforeprint', function() {
          calculatePages();
        });
      };
